GetWebHostingUploadCredential.responseParamsDescription:
Sample file upload method:  
```nodejs  
async function uploadFile(file) {  
    try {  
        // 1. Obtain upload credentials  
        const credentials = await getUploadCredentials();  

        // 2. Build the upload form  
        const formData = new FormData();  
        formData.append('policy', credentials.Policy);  
        formData.append('OSSAccessKeyId', credentials.AccessKeyId);  
        formData.append('success_action_status', '200');  
        formData.append('signature', credentials.Signature);  
        formData.append('x-oss-security-token', credentials.SecurityToken);  
        formData.append('key', credentials.FilePath + file.name);  
        // Note: The 'file' field must be appended last  
        formData.append('file', file);  

        // 3. Execute the upload  
        const uploadResponse = await fetch(`https://${credentials.Endpoint}`, {  
            method: 'POST',  
            body: formData  
        });  

        if (uploadResponse.status === 200) {  
            const fileUrl = `https://${credentials.Endpoint}/${credentials.FilePath}${file.name}`;  
            console.log('File Upload Succeeded:', fileUrl);  
            return {  
                success: true,  
                url: fileUrl,  
                filename: file.name  
            };  
        } else {  
            throw new Error(`Upload failed, status code: ${uploadResponse.status}`);  
        }  

    } catch (error) {  
        console.error('Failed to Upload File:', error);  
        return {  
            success: false,  
            error: error.message  
        };  
    }  
}  
```

